const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.arrow}"/></svg>`;
const assets=[{s:'BTC',name:'Bitcoin',icon:'₿',cls:'btc',p:69466.67,net:'Bitcoin',change:2.41},{s:'ETH',name:'Ethereum',icon:'♦',cls:'eth',p:3420.52,net:'Ethereum',change:3.82},{s:'SOL',name:'Solana',icon:'≋',cls:'sol',p:166.1,net:'Solana',change:-1.24},{s:'USDC',name:'USD Coin',icon:'$',cls:'usdc',p:1,net:'Ethereum',change:.01}];
const initial={version:2,balances:{BTC:.15,ETH:2.292,SOL:20,USDC:3000.42},cash:10000,prefs:{name:'Explorer',hide:false,notifications:true,lock:false},checks:{},txs:[{id:'DEMO-0003',type:'Received',s:'ETH',qty:.2,value:684.1,date:'2026-10-17T04:42:00Z',status:'Completed',network:'Ethereum',fee:0,recipient:'Example wallet',sample:true},{id:'DEMO-0002',type:'Swapped',s:'ETH',to:'USDC',qty:.15,out:511.04,value:513.08,date:'2026-10-16T18:18:00Z',status:'Completed',network:'Ethereum',fee:2.04,sample:true},{id:'DEMO-0001',type:'Sent',s:'USDC',qty:250,value:250,date:'2026-10-14T15:30:00Z',status:'Completed',network:'Ethereum',fee:1,recipient:'Sample recipient',sample:true}]};
let state;try{state=JSON.parse(localStorage.getItem('fynx-wallet-v2'));if(state?.version!==2)throw Error()}catch{state=structuredClone(initial)}
function save(){try{localStorage.setItem('fynx-wallet-v2',JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes last for this visit.')}}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coin=s=>assets.find(c=>c.s===s),price=s=>s==='USD'?1:coin(s).p,fmt=(n,d=6)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d}),money=n=>Number(n).toLocaleString('en-US',{style:'currency',currency:'USD'}),coinIcon=s=>`<span class="coin ${coin(s).cls}">${coin(s).icon}</span>`,total=()=>assets.reduce((n,c)=>n+state.balances[c.s]*c.p,0);
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal()}
$('#dialog-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
$('#menu').innerHTML=icon('menu');$('#menu').onclick=()=>{const open=$('#mobile-links').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};
const btn=(txt,href,cls='')=>`<a class="button ${cls}" href="#${href}">${txt}</a>`;
const appTabs=[['wallet','Overview','grid'],['assets','Assets','wallet'],['buy','Buy & sell','plus'],['swap','Swap','swap'],['activity','Activity','activity'],['settings','Settings','settings']];
function shell(title,sub,body,active){return `<div class="app-header"><div><span class="eyebrow">FYNX WALLET / ${active==='guide'?'BUILD GUIDE':'YOUR SPACE'}</span><h1>${title}</h1><p>${sub}</p></div><span class="pill">${icon('globe')} Interactive demo</span></div><nav class="app-tabs" aria-label="Wallet pages">${appTabs.map(([k,t,i])=>`<a href="#${k}" class="${active===k||(active==='sell'&&k==='buy')?'active':''}">${icon(i)}${t}</a>`).join('')}</nav>${body}`}
function assetTable(list=assets){return `<div class="card table-wrap"><table><thead><tr><th>Asset</th><th class="price-col">Sample price</th><th>24h · sample</th><th>Your balance</th></tr></thead><tbody>${list.map(c=>`<tr class="asset-row" tabindex="0" role="link" aria-label="View ${c.name}" data-asset="${c.s}"><td><div class="flex">${coinIcon(c.s)}<span><span class="asset-name">${c.name}</span><span class="asset-ticker">${c.s} · ${c.net}</span></span></div></td><td class="price-col">${money(c.p)}</td><td class="${c.change<0?'down':'up'}">${c.change>0?'+':''}${c.change}%</td><td><b style="font-weight:500">${state.prefs.hide?'••••':money(state.balances[c.s]*c.p)}</b><span class="asset-ticker">${state.prefs.hide?'••••':fmt(state.balances[c.s])} ${c.s}</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching assets. Try another symbol or name.</td></tr>'}</tbody></table></div>`}
function txTitle(t){return `${t.type} ${t.s}${t.to?' → '+t.to:''}`}function txList(list=state.txs,limit=100){return list.slice(0,limit).map(t=>`<button class="tx-row" data-tx="${escape(t.id)}"><span class="iconbutton">${icon(t.type==='Sent'?'arrow':t.type==='Swapped'?'swap':'down')}</span><span class="tx-main">${txTitle(t)}<small>${new Date(t.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${t.network} · simulated</small></span><span class="tx-sum">${t.type==='Sent'||t.type==='Sold'?'−':'+'}${fmt(t.qty)} ${t.s}<small>${t.status}${t.to?' · '+fmt(t.out)+' '+t.to:''}</small></span></button>`).join('')||'<div class="empty">No transactions match this filter.</div>'}
function chartMarkup(){return `<div class="chart-tools"><span class="tiny">Illustrative performance</span><div class="ranges">${['1D','1W','1M','1Y','ALL'].map(r=>`<button data-range="${r}" class="${r==='1M'?'active':''}">${r}</button>`).join('')}</div></div><svg class="chart" viewBox="0 0 700 170" preserveAspectRatio="none" role="img" aria-label="Illustrative portfolio performance"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#939c96" stop-opacity=".13"/><stop offset="1" stop-color="#939c96" stop-opacity="0"/></linearGradient></defs><path d="M0 30H700M0 90H700M0 150H700" stroke="#ededee" stroke-dasharray="3 6"/><path id="chart-area" fill="url(#fade)"/><path id="chart-line" fill="none" stroke="#58665d" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="dates" id="chart-dates"></div>`}
function home(){return `<section class="hero"><div><span class="pill">Introducing the FYNX Wallet concept</span><h1>Your crypto.<br>Simply yours.</h1><p>A little less complexity.<br>A lot more possibility. Meet a calmer place to manage your digital assets.</p><div class="cta">${btn('Explore the wallet '+icon('arrow'),'wallet')}${btn('See what needs connecting','guide','light')}</div><span class="tiny">Interactive preview. No real funds connected.</span></div><div class="hero-art"><div class="hero-wallet"><div class="between"><span class="tiny">Your portfolio</span><span class="pill">Demo</span></div><div class="amount">${money(total())}</div><span class="gain">↗ 5.35% <span>illustrative past month</span></span><div class="mini-actions"><a href="#buy">+ Buy</a><a href="#send">↗ Send</a><a href="#swap">⇄ Swap</a></div>${assets.slice(0,3).map(c=>`<a class="setting-row" style="padding:14px 0" href="#asset/${c.s}"><span class="flex">${coinIcon(c.s)}<span><span class="asset-name">${c.name}</span><span class="asset-ticker">${fmt(state.balances[c.s])} ${c.s}</span></span></span><b style="font-size:12px;font-weight:500">${money(state.balances[c.s]*c.p)}</b></a>`).join('')}</div><div class="float-chip"><span class="iconbutton">${icon('down')}</span><div>Every move, in one place.<div class="tiny">Send. Receive. Swap. Repeat.</div></div></div></div></section><section class="soft-section"><div class="sectiontop"><div><div class="eyebrow">MADE FOR YOUR EVERYDAY</div><h2 style="margin-top:12px">Everything has its place.</h2></div><a class="textlink" href="#assets">Meet your assets ${icon('arrow')}</a></div><div class="feature-grid"><article class="feature">${icon('wallet')}<h3>A clear view of your crypto.</h3><p>Balances, assets, and the little details that make your portfolio easier to understand.</p><a class="textlink" href="#wallet">Explore portfolio ${icon('arrow')}</a></article><article class="feature">${icon('swap')}<h3>More ways to move.</h3><p>Try a purchase, preview a swap, or follow a transfer from review to confirmation.</p><a class="textlink" href="#buy">Try a demo purchase ${icon('arrow')}</a></article><article class="feature">${icon('shield')}<h3>Clarity comes first.</h3><p>Understand what’s in the preview, what still needs connecting, and what it takes to launch.</p><a class="textlink" href="#guide">Read the build guide ${icon('arrow')}</a></article></div></section><section class="soft-section"><div class="tour"><div><span class="eyebrow">A SMALL TOUR. A BIGGER PICTURE.</span><h2 style="font-size:34px;margin-top:18px">From your first click<br>to your next move.</h2><p class="muted" style="font-size:13px">Explore the product before connecting a single service.</p>${btn('Step inside '+icon('arrow'),'wallet')}</div><div class="steps"><div class="step"><span class="number">01</span><div><b>Get the full picture</b><span class="muted">Open your portfolio and explore each asset.</span></div></div><div class="step"><span class="number">02</span><div><b>Try the complete flow</b><span class="muted">Enter an amount, review sample fees, and simulate a transaction.</span></div></div><div class="step"><span class="number">03</span><div><b>Know what comes next</b><span class="muted">See providers, launch requirements, and the decisions you’ll make.</span></div></div></div></div></section>`}
function wallet(){return shell(`Welcome back, ${escape(state.prefs.name)}.`,'Your crypto, with a little more perspective.',`<div class="grid"><div><div class="card pad"><div class="between"><span class="tiny">Total portfolio value <button class="textlink" data-act="hide" aria-label="Toggle balance visibility">${icon('eye')}</button></span><span class="pill">USD</span></div><div class="total">${state.prefs.hide?'$••,•••.••':money(total())}</div><div class="gain">↗ Sample chart <span>Balances update when you simulate a trade</span></div>${chartMarkup()}<div class="wallet-actions">${[['buy','Buy','plus'],['sell','Sell','minus'],['send','Send','arrow'],['receive','Receive','down'],['swap','Swap','swap']].map(([k,t,i])=>`<a href="#${k}"><span class="iconbutton">${icon(i)}</span>${t}</a>`).join('')}</div></div><div class="section-title"><h2>Your assets</h2><a class="textlink" href="#assets">View all ${icon('arrow')}</a></div>${assetTable()}</div><aside class="dashboard-side"><div class="card pad"><span class="eyebrow">YOUR NEXT MOVE</span><h2 style="font-size:25px;margin:15px 0">Crypto, at your pace.</h2><p class="muted" style="font-size:12px">Explore a complete purchase flow, from amount to confirmation.</p>${btn('Buy crypto '+icon('plus'),'buy','wide')}<div class="subcard"><div class="between"><span class="tiny">Simulated spending balance</span>${icon('wallet')}</div><h3 style="margin:10px 0">${money(state.cash)}</h3><span class="tiny">Demo money for testing buys. No bank account.</span></div></div><div class="section-title"><h2>Recent activity</h2><a class="textlink" href="#activity">See all ↗</a></div><div class="card pad"><div class="between"><h3 style="font-size:14px;margin:0">Latest moves</h3><a class="textlink" href="#activity">↗</a></div>${txList(state.txs,3)}</div></aside></div><div class="inline-banner"><div><b style="font-size:13px">A working preview. A clear path to launch.</b><p>See exactly which services turn these flows into a live product.</p></div>${btn('View connection guide ↗','guide','light')}</div>`,'wallet')}
function allAssets(){return shell('Every asset. One place.','Explore your holdings and open an asset for more detail.',`<div class="section-title"><h2>My assets <span class="tiny">· 4 assets</span></h2><input class="control small" id="asset-search" placeholder="Search name or symbol" aria-label="Search assets"></div><div id="asset-results">${assetTable()}</div><div class="two-cols" style="margin-top:24px"><div class="card pad"><h3>Portfolio allocation</h3><div class="allocation">${assets.map(c=>`<span class="seg" style="width:${state.balances[c.s]*c.p/total()*100}%;background:${({BTC:'#d9ba91',ETH:'#a6a6bd',SOL:'#99b6a4',USDC:'#a5bace'})[c.s]}"></span>`).join('')}</div><div class="legend">${assets.map(c=>`<span>${c.s} ${fmt(state.balances[c.s]*c.p/total()*100,1)}%</span>`).join('')}</div></div><div class="card pad"><h3>A note on networks</h3><p class="muted" style="font-size:12px">USDC exists on multiple networks. This demo uses USDC on Ethereum. Bitcoin needs a separate live wallet integration.</p><a class="textlink" href="#networks">Explore network coverage ↗</a></div></div>`,'assets')}
function assetDetail(s){let c=coin(s);if(!c)return allAssets();return shell(c.name,'Your holding, transactions, and network details.',`<a class="textlink back" href="#assets">← Back to assets</a><div class="grid assetdetail"><div><div class="card pad"><div class="between"><span class="flex">${coinIcon(s)}<span>${c.name}<span class="asset-ticker">${c.net} network</span></span><span class="pill">Sample data</span></div><div class="total">${state.prefs.hide?'••••':money(state.balances[s]*c.p)}</div><p class="muted">${state.prefs.hide?'••••':fmt(state.balances[s])} ${s}</p><div class="between"><span class="tiny">Illustrative unit price</span><span>${money(c.p)}</span></div><div class="mini-actions"><a href="#buy/${s}">Buy</a><a href="#sell/${s}">Sell</a><a href="#send/${s}">Send</a><a href="#receive/${s}">Receive</a></div></div><div class="section-title"><h2>${c.name} activity</h2></div><div class="card pad">${txList(state.txs.filter(t=>t.s===s||t.to===s))}</div></div><div class="card pad"><h3>Network details</h3><div class="fee-row"><span>Network</span><strong>${c.net}</strong></div><div class="fee-row"><span>Symbol</span><strong>${s}</strong></div><div class="fee-row"><span>Connection</span><strong>Not connected</strong></div><div class="info-box">${s==='BTC'?'Bitcoin is shown for design exploration. Its signing, UTXO management, fees, and history need a separate Bitcoin-compatible provider.':'A live wallet SDK will create an address, retrieve balances, and request user authorization to sign transactions.'}</div>${btn('Connection details ↗','guide','light wide')}</div></div>`,'assets')}
const tradeCopy={buy:['A little closer to crypto.','Choose an amount, see what you receive, and review everything before you continue.'],sell:['From crypto to possibility.','Preview a sale with clear amounts and an example payout.'],swap:['A change of direction.','Exchange Ethereum assets with a clear view of the rate, fees, and final amount.'],send:['Send with a clear view.','Choose the asset, add a demo recipient, and review the transfer.'],receive:['A place for your next transfer.','Explore the receiving screen for each network.']};
function tradePage(mode,s){let c=coin(s)||coin('ETH');return shell(({buy:'Buy & sell',sell:'Buy & sell',swap:'Swap crypto',send:'Send crypto',receive:'Receive crypto'})[mode],'A complete demo flow. No real funds or accounts.',`<div class="trade-layout"><div class="trade-intro"><span class="pill">${icon(mode==='swap'?'swap':mode==='receive'?'down':mode==='send'?'arrow':'wallet')} FYNX ${mode}</span><h2 style="margin-top:22px">${tradeCopy[mode][0]}</h2><p>${tradeCopy[mode][1]}</p><div class="steps" style="margin-top:30px">${['Choose your details','Review the full picture','Simulate a confirmation'].map((x,i)=>`<div class="step"><span class="number">0${i+1}</span><div><b>${x}</b><span class="muted">${['Sample data only.','Amounts and fees, in one place.','Portfolio and activity update locally.'][i]}</span></div></div>`).join('')}</div><div class="info-box"><strong>What makes this live?</strong><br>${mode==='buy'||mode==='sell'?'An approved payment provider, real quotes, identity checks, verified webhooks, and a connected wallet.':mode==='swap'?'Live liquidity quotes, token approvals, user signing, gas estimation, and blockchain confirmation.':'A wallet provider, network validation, transaction signing, and blockchain monitoring.'}<br><a class="textlink" href="#guide" style="margin-top:10px">Read the connection guide ↗</a></div></div><div class="trade-box" id="trade-box">${mode==='receive'?receiveForm(c.s):mode==='send'?sendForm(c.s):exchangeForm(mode,c.s)}</div></div>`,mode==='send'||mode==='receive'?'wallet':mode)}
function options(ss,selected){return ss.map(s=>`<option value="${s}" ${s===selected?'selected':''}>${s==='USD'?'USD':coin(s).name+' · '+s}</option>`).join('')}
let currentTrade=null;
function exchangeForm(mode,s){let f=mode==='buy'?'USD':s,t=mode==='sell'?'USD':mode==='swap'?'USDC':s;if(f===t)t='ETH';return `${mode==='buy'||mode==='sell'?`<div class="tabs"><button class="${mode==='buy'?'active':''}" data-go="buy/${s}">Buy</button><button class="${mode==='sell'?'active':''}" data-go="sell/${s}">Sell</button></div>`:`<div class="between" style="margin-bottom:22px"><h3 style="margin:0">Swap</h3><span class="pill">Ethereum only</span></div>`}<form id="exchange-form" data-mode="${mode}"><div class="moneybox"><span class="tiny">You ${mode==='sell'?'sell':'pay'}</span><div class="moneyrow"><input type="number" id="amount" value="${mode==='buy'?100:mode==='sell'?.1:1}" min="0" step="any" aria-label="Amount to ${mode}" required><select id="pay-asset" aria-label="Pay asset">${options(mode==='buy'?['USD']:mode==='swap'?['ETH','USDC']:assets.map(c=>c.s),f)}</select></div><span class="tiny" id="available"></span></div>${mode==='swap'?`<button type="button" class="switcher" id="reverse" aria-label="Reverse assets">${icon('swap')}</button>`:''}<div class="moneybox"><span class="tiny">You receive · estimated demo</span><div class="moneyrow"><output id="receive-amount">—</output><select id="receive-asset" aria-label="Receive asset">${options(mode==='sell'?['USD']:mode==='swap'?['USDC','ETH']:assets.map(c=>c.s),t)}</select></div><span class="tiny" id="trade-rate"></span></div>${mode!=='swap'?`<label class="label" for="payment">${mode==='buy'?'Payment method':'Payout method'}</label><select class="control" id="payment"><option>Demo bank account</option><option>${mode==='buy'?'Demo debit card':'Demo eligible card'}</option></select>`:`<label class="label" for="slippage">Slippage tolerance · preview preference</label><select class="control" id="slippage"><option value="0.5">0.5%</option><option value="1">1%</option><option value="2">2%</option></select>`}<div id="fee-details"></div><label class="label" for="scenario">Test a demo outcome</label><select id="scenario" class="control"><option value="success">Successful confirmation</option><option value="unavailable">Provider unavailable</option><option value="rejected">Authorization rejected</option></select><div class="error" id="trade-error" role="alert"></div><button class="button wide" type="submit">Review demo ${mode} ${icon('arrow')}</button><p class="hint">Sample rates and invented fee assumptions. Not a live quote. No card details are collected.</p></form>`}
function quoteExchange(){const mode=$('#exchange-form').dataset.mode,n=Number($('#amount').value),f=$('#pay-asset').value,t=$('#receive-asset').value;const gross=Math.max(0,n||0)*price(f),provider=gross*(mode==='swap'?.003:.005),network=mode==='buy'?0:1,net=gross-provider-network,out=Math.max(0,net)/price(t);$('#receive-amount').textContent=fmt(out,t==='USD'?2:6);$('#trade-rate').textContent=`1 ${f} = ${fmt(price(f)/price(t))} ${t} · sample`;$('#available').textContent='Available: '+(f==='USD'?money(state.cash):fmt(state.balances[f])+' '+f)+' · simulated';$('#fee-details').innerHTML=`<div class="fee-row"><span>Demo provider fee (${mode==='swap'?'0.3':'0.5'}%)</span><strong>${money(provider)}</strong></div><div class="fee-row"><span>Demo network fee</span><strong>${money(network)}</strong></div><div class="fee-row fee-total"><span>Total value paid</span><strong>${money(gross)}</strong></div>`;currentTrade={mode,n,f,t,gross,provider,network,out,fee:provider+network};return currentTrade}
function bindExchange(){if(!$('#exchange-form'))return;quoteExchange();['amount','pay-asset','receive-asset'].forEach(id=>$('#'+id).oninput=()=>{quoteExchange();$('#trade-error').textContent=''});if($('#reverse'))$('#reverse').onclick=()=>{const f=$('#pay-asset').value;$('#pay-asset').value=$('#receive-asset').value;$('#receive-asset').value=f;quoteExchange()};$('#exchange-form').onsubmit=e=>{e.preventDefault();const q=quoteExchange();let error='';if(!Number.isFinite(q.n)||q.n<=0)error='Enter a positive amount.';else if(q.f===q.t)error='Choose two different assets.';else if(q.n>(q.f==='USD'?state.cash:state.balances[q.f]))error='This amount exceeds your simulated available balance.';else if(q.out<=0)error='The amount is too small to cover the demo fees.';if(error){$('#trade-error').textContent=error;return}const scenario=$('#scenario').value,payment=$('#payment')?.value||'Ethereum wallet',slippage=$('#slippage')?.value;reviewTrade({...q,scenario,payment,slippage})}}
function reviewTrade(q){modal(`Review your ${q.mode}`,`<span class="pill">Simulation · no real funds</span><div class="receipt" style="margin-top:18px"><div class="fee-row"><span>You pay</span><strong>${fmt(q.n)} ${q.f}</strong></div><div class="fee-row"><span>You receive</span><strong>${fmt(q.out)} ${q.t}</strong></div><div class="fee-row"><span>Demo fees included</span><strong>${money(q.fee)}</strong></div><div class="fee-row"><span>${q.mode==='swap'?'Network':'Method'}</span><strong>${escape(q.payment)}</strong></div>${q.slippage?`<div class="fee-row"><span>Minimum received at ${q.slippage}% slippage</span><strong>${fmt(q.out*(1-Number(q.slippage)/100))} ${q.t}</strong></div>`:''}</div><p class="hint">Confirmation updates only this browser’s demo portfolio. A real provider would supply an expiring quote and final fees.</p><button id="confirm-trade" class="button wide">Confirm simulation ${icon('check')}</button><button class="textlink wide" style="margin-top:15px" id="edit-trade">Go back and edit</button>`);$('#edit-trade').onclick=()=>$('#dialog').close();$('#confirm-trade').onclick=()=>simulate(q)}
function simulate(q){$('#dialog-body').innerHTML='<div class="result-icon skeleton">…</div><h3 style="text-align:center">Simulating your request</h3><p style="text-align:center">No provider or blockchain is being contacted.</p>';$('#dialog-close').disabled=true;setTimeout(()=>{const success=q.scenario==='success';const tx={id:'DEMO-'+Date.now().toString(36).toUpperCase(),type:q.mode==='buy'?'Bought':q.mode==='sell'?'Sold':q.mode==='swap'?'Swapped':'Sent',s:q.f==='USD'?q.t:q.f,to:q.mode==='swap'?q.t:undefined,qty:q.mode==='buy'?q.out:q.n,out:q.out,value:q.gross,date:new Date().toISOString(),status:success?'Completed':'Failed',network:q.mode==='swap'?'Ethereum':coin(q.f==='USD'?q.t:q.f).net,fee:q.fee,recipient:q.recipient,method:q.payment,sample:true};if(success){if(q.f==='USD')state.cash-=q.n;else state.balances[q.f]-=q.n;if(q.mode!=='send'){if(q.t==='USD')state.cash+=q.out;else state.balances[q.t]+=q.out}}state.txs.unshift(tx);save();$('#dialog-close').disabled=false;$('#dialog-title').textContent=success?'Demo complete':'Demo request failed';$('#dialog-body').innerHTML=`<div class="result-icon ${success?'':'failed'}">${success?'✓':'×'}</div><h3 style="text-align:center">${success?'Your preview has been updated.':q.scenario==='unavailable'?'Provider unavailable.':'Authorization rejected.'}</h3><p style="text-align:center">${success?'The simulated transaction appears in your activity. No real money moved.':'Your demo balance is unchanged. This simulated failure is recorded in your activity.'}</p><div class="receipt"><div class="fee-row"><span>Demo reference</span><strong>${tx.id}</strong></div><div class="fee-row"><span>Status</span><strong>${tx.status}</strong></div></div><button class="button wide" id="view-tx">View transaction ${icon('arrow')}</button><button class="textlink wide" id="try-again" style="margin-top:18px">${success?'Back to wallet':'Try again'}</button>`;$('#view-tx').onclick=()=>{$('#dialog').close();location.hash='transaction/'+tx.id};$('#try-again').onclick=()=>{$('#dialog').close();if(success)location.hash='wallet';else render()};},750)}
function sendForm(s){return `<h3>Send crypto</h3><form id="send-form"><label class="label" for="send-asset">Asset & network</label><select class="control" id="send-asset">${options(assets.map(c=>c.s),s)}</select><label class="label" for="recipient">Demo recipient label</label><input class="control" id="recipient" required maxlength="60" placeholder="e.g. My second wallet"><span class="hint" style="display:block">Use a made-up label. Real address validation is a future integration.</span><label class="label" for="send-amount">Amount</label><div class="flex"><input class="control" type="number" min="0" step="any" id="send-amount" placeholder="0.00" required><button type="button" id="send-max" class="button soft">Max</button></div><p class="hint" id="send-balance"></p><div class="info-box" id="send-net"></div><div class="fee-row"><span>Demo network fee · deducted from amount</span><strong>$1.00</strong></div><label class="label" for="scenario">Test a demo outcome</label><select id="scenario" class="control"><option value="success">Successful confirmation</option><option value="unavailable">Provider unavailable</option><option value="rejected">Authorization rejected</option></select><div class="error" id="send-error" role="alert"></div><button class="button wide">Review demo transfer ${icon('arrow')}</button></form>`}
function bindSend(){if(!$('#send-form'))return;const update=()=>{let s=$('#send-asset').value;$('#send-balance').textContent=`Available: ${fmt(state.balances[s])} ${s} · simulated`;$('#send-net').textContent=`Network: ${coin(s).net}. A live transfer must validate the recipient on this network, estimate the fee, and request your signature.`};$('#send-asset').onchange=update;$('#send-max').onclick=()=>$('#send-amount').value=state.balances[$('#send-asset').value];update();$('#send-form').onsubmit=e=>{e.preventDefault();let s=$('#send-asset').value,n=Number($('#send-amount').value),recipient=$('#recipient').value.trim(),error='';if(!recipient)error='Add a demo recipient label.';else if(!Number.isFinite(n)||n<=0)error='Enter a positive amount.';else if(n>state.balances[s])error='This exceeds your simulated balance.';else if(n*price(s)<=1)error='The amount must cover the $1 demo network fee.';if(error){$('#send-error').textContent=error;return}let q={mode:'send',n,f:s,t:s,gross:n*price(s),fee:1,out:n-1/price(s),recipient,scenario:$('#scenario').value};modal('Review your transfer',`<div class="receipt"><div class="fee-row"><span>Recipient label</span><strong>${escape(recipient)}</strong></div><div class="fee-row"><span>Network</span><strong>${coin(s).net}</strong></div><div class="fee-row"><span>Deducted from wallet</span><strong>${fmt(n)} ${s}</strong></div><div class="fee-row"><span>Recipient gets</span><strong>${fmt(q.out)} ${s}</strong></div><div class="fee-row"><span>Demo fee included</span><strong>$1.00</strong></div></div><p class="hint">No valid destination address or signing key is used. This updates only the local demo ledger.</p><button class="button wide" id="confirm-send">Confirm simulation ${icon('check')}</button>`);$('#confirm-send').onclick=()=>simulate(q)}}
function receiveForm(s){return `<h3>Receive crypto</h3><label class="label" for="receive-coin">Asset & network</label><select class="control" id="receive-coin">${options(assets.map(c=>c.s),s)}</select><div class="subcard" style="text-align:center;padding:28px 15px"><span class="iconbutton" style="width:60px;height:60px">${icon('down')}</span><h3 style="margin:18px 0 6px" id="receive-title"></h3><span class="tiny">No live receiving address has been created.</span></div><label class="label">Example identifier · not a blockchain address</label><div class="address" id="receive-address"></div><button class="button light wide" style="margin-top:17px" id="copy-address">${icon('copy')} Copy demo identifier</button><div class="info-box">A live version will create a real address and a scannable QR code for the selected network. Never send funds to the demo identifier.</div>${btn('What needs connecting ↗','guide','soft wide')}`}
function bindReceive(){if(!$('#receive-coin'))return;let update=()=>{const c=coin($('#receive-coin').value);$('#receive-title').textContent=c.name+' on '+c.net;$('#receive-address').textContent='FYNX-DEMO-'+c.s+'-NOT-A-REAL-ADDRESS'};$('#receive-coin').onchange=update;update();$('#copy-address').onclick=()=>copy($('#receive-address').textContent)}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Copied to clipboard')}catch{modal('Copy this text',`<textarea class="control" rows="5" readonly>${escape(s)}</textarea><p class="hint">Select the text and copy it manually.</p>`)}}
function activity(){return shell('Follow every move.','Your simulated transactions, from the first step to the final detail.',`<div class="section-title"><div class="flex"><select class="control small" id="activity-filter" aria-label="Filter transaction type"><option value="all">All types</option>${['Bought','Sold','Sent','Received','Swapped'].map(x=>`<option>${x}</option>`).join('')}</select><select class="control small" id="status-filter" aria-label="Filter transaction status"><option value="all">All statuses</option><option>Completed</option><option>Failed</option></select></div><button class="textlink" data-act="export">${icon('download')} Export demo CSV</button></div><div class="card pad" id="activity-list">${txList()}</div><p class="hint">Entries are sample records and locally simulated actions, not blockchain transactions.</p>`,'activity')}
function txDetail(id){let t=state.txs.find(t=>t.id===id);if(!t)return shell('Transaction not found.','This demo record may have been reset.',btn('Back to activity','activity'),'activity');return shell('The full picture.','Every detail of your simulated transaction.',`<a href="#activity" class="textlink back">← All activity</a><div class="trade-box" style="max-width:620px;margin:0 auto"><div class="result-icon ${t.status==='Failed'?'failed':''}">${t.status==='Failed'?'×':'✓'}</div><h2 style="text-align:center">${txTitle(t)}</h2><p class="muted" style="text-align:center">${fmt(t.qty)} ${t.s}</p><div class="receipt">${[['Status',t.status],['Demo reference',t.id],['Date',new Date(t.date).toLocaleString()],['Network',t.network],['Illustrative value',money(t.value)],['Demo fees',money(t.fee)],...(t.to?[['Received',fmt(t.out)+' '+t.to]]:[]),...(t.recipient?[['Recipient label',t.recipient]]:[])].map(([k,v])=>`<div class="fee-row"><span>${k}</span><strong class="break">${escape(v)}</strong></div>`).join('')}</div><p class="hint">No on-chain hash exists for this simulated entry. A live record would include confirmed network status and an explorer link.</p><button class="button light wide" id="copy-reference" data-reference="${escape(t.id)}">${icon('copy')} Copy demo reference</button></div>`,'activity')}
function settings(tab='profile'){let body='';if(tab==='profile')body=`<h3>Your demo profile</h3><p class="tiny">A display preference in this browser. No login account is created.</p><form id="profile-form"><label class="label" for="display-name">Display name</label><input class="control" id="display-name" maxlength="30" required value="${escape(state.prefs.name)}"><button class="button" style="margin-top:18px">Save profile ${icon('check')}</button></form>`;if(tab==='preferences')body=`<h3>Make it feel like yours.</h3><div class="setting-row"><div><h3>Hide portfolio amounts</h3><p>Mask balances across your portfolio and asset screens.</p></div><button class="toggle" role="switch" aria-label="Hide portfolio amounts" aria-checked="${state.prefs.hide}" data-pref="hide"></button></div><div class="setting-row"><div><h3>Demo notification preference</h3><p>Saved locally. Real email and push notifications require a messaging service.</p></div><button class="toggle" role="switch" aria-label="Demo notifications" aria-checked="${state.prefs.notifications}" data-pref="notifications"></button></div><div class="setting-row"><div><h3>Display currency</h3><p>USD is used for every illustrative quote.</p></div><span class="pill">USD</span></div>`;if(tab==='connections')body=`<h3>Connected services</h3><p class="tiny">No service below is connected. Demo status does not indicate provider approval.</p>${[['Wallet provider','Circle or alternative'],['Buy & sell','MoonPay or alternative'],['Liquidity','0x or alternative'],['Account login','Firebase / Auth0'],['Market data','Price feed & indexer']].map(([a,b])=>`<div class="setting-row"><div><h3>${a}</h3><p>${b}</p></div><span class="pill">Not connected</span></div>`).join('')}${btn('See the full connection plan ↗','guide','light wide')}`;if(tab==='data')body=`<h3>Your preview data</h3><p class="muted" style="font-size:12px">Balances, sample transactions, preferences, and guide checklist choices are stored in this browser. They are not secure financial records and do not sync between devices.</p><div class="setting-row"><div><h3>Export demo activity</h3><p>Download a CSV of sample and simulated transactions.</p></div><button class="button light" data-act="export">Export CSV</button></div><div class="setting-row"><div><h3>Reset the preview</h3><p>Restore the initial sample balances and remove local changes.</p></div><button class="button light" data-act="reset">Reset demo</button></div>`;return shell('Make yourself at home.','A few thoughtful preferences for your preview.',`<div class="settings-nav">${['profile','preferences','connections','data'].map(t=>`<button data-go="settings/${t}" class="${tab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="card pad" style="max-width:800px">${body}</div>`,'settings')}
function security(){return shell('Trust starts with clarity.','What the preview does today, and what a live wallet will need.',`<div class="guide-hero"><span class="pill">Concept stage · no audit or certification claimed</span><h2>Built around your control.<br>Designed with care.</h2><p class="muted">A user-controlled wallet is the proposed direction. In that model, the wallet provider helps users authorize transactions. Choosing a provider is only the first step.</p></div><div class="security-grid"><div class="card security-card">${icon('lock')}<h3>User-controlled signing</h3><p>Plan for signing and recovery through a proven wallet SDK. FYNX should never ask users to paste a recovery phrase into a support form.</p><a href="#guide" class="textlink">Wallet architecture ↗</a></div><div class="card security-card">${icon('shield')}<h3>Account protection</h3><p>Before launch: real authentication, passkeys or MFA, session controls, authorization checks, rate limits, and alerts for suspicious activity.</p><button class="textlink" data-act="session-demo">Explore a session control ↗</button></div><div class="card security-card">${icon('activity')}<h3>Transaction safeguards</h3><p>Network checks, final fee review, expiring quotes, granular token approvals, clear signing prompts, and transaction monitoring.</p><a href="#send" class="textlink">Explore the transfer preview ↗</a></div><div class="card security-card">${icon('help')}<h3>A clear recovery path</h3><p>Test lost-device and account-recovery flows before launch. Document the recovery design for each supported wallet type.</p><button class="textlink" data-act="recovery">Read the recovery plan ↗</button></div></div><div class="two-cols" style="margin-top:24px"><div class="card pad"><h3>What is active in this preview?</h3><p class="muted" style="font-size:12px">Local input checks, escaped user text, sample transaction history, and browser-local preferences. No real authentication, key storage, blockchain access, or provider monitoring is active.</p><a href="#settings/data" class="textlink">Manage local preview data ↗</a></div><div class="card pad"><h3>Report a concern</h3><p class="muted" style="font-size:12px">Prepare a security report draft. A verified reporting channel and response process are needed before launch.</p><a href="#support/security" class="textlink">Prepare a security report ${icon('arrow')}</a></div></div>`,'security')}
const docs={moon:'https://support.moonpay.com/en/articles/388689-how-to-go-live-with-moonpay-as-a-partner',circle:'https://developers.circle.com/wallets/supported-blockchains',swap:'https://docs.0x.org/docs/introduction/quickstart/swap-tokens-with-0x-swap-api',alchemy:'https://www.alchemy.com/docs/reference/notify-api-quickstart',legal:'https://www.fincen.gov/resources/statutes-regulations/guidance/application-fincens-regulations-certain-business-models'};
const providers=[{name:'Wallets & signing',provider:'Circle user-controlled wallets, or a compatible alternative',mark:'C',desc:'Creates wallets and requests user authorization to sign transfers. Start with a single network; expand only after signing and recovery work end to end.',steps:['Decide who controls funds and document the recovery model.','Create a developer project and keep private API credentials on the server.','Connect SDK authorization to your real user identity.','Prove wallet creation, restore, balances, signing, and rejected-signature handling on testnets.','Circle currently lists Ethereum, Base, and Solana among supported networks. Bitcoin is not listed: plan a separate Bitcoin provider and UTXO implementation.'],href:docs.circle},{name:'Buy & sell with cards or banks',provider:'MoonPay on-ramp / off-ramp',mark:'M',desc:'Use an approved provider for fiat purchases and payouts. The provider checkout handles supported payment methods and required user verification; do not collect raw card data in FYNX.',steps:['Create the partner account, submit the project, complete account review and business verification (KYB).','Build with test keys; choose supported assets, networks, regions, and payment methods.','Use a hosted widget/SDK first. Configure allowed domains, server-side signing where required, and verified webhooks.','Handle pending, failed, refunded, and completed orders without duplicate credits.','Obtain per-product approval, production keys, and activation before processing real payments. Headless integrations have an additional acceptance review.'],href:docs.moon},{name:'Swap quotes & liquidity',provider:'0x for an initial Ethereum / EVM swap flow',mark:'0x',desc:'Retrieves a price and firm quote for compatible assets. FYNX must still validate the quote, show fees, request user approval, sign, broadcast, and track the transaction.',steps:['Create a 0x project and protect API credentials in the backend.','Request an indicative price, check balances, and inspect required token allowance.','Fetch an expiring firm quote, display price impact, gas, fees, and minimum received.','Use the correct allowance spender and a granular approval; request user signing.','Track settlement. ETH ↔ USDC on Ethereum is the proposed initial scope; Solana and cross-chain swaps need separately validated integrations.'],href:docs.swap},{name:'Blockchain data & notifications',provider:'Wallet-provider APIs + Alchemy where needed',mark:'A',desc:'Fetches balances and transfer history, broadcasts supported transactions, and tracks changes. Reuse wallet-provider capabilities before adding overlapping services.',steps:['Select an RPC/indexer for each supported chain and define confirmation requirements.','Validate webhook signatures and process events idempotently.','Reconcile provider order IDs with on-chain hashes; handle reorgs and retry safely.','Never mark a payment complete from the browser redirect alone.','Add stale-price labels, outage handling, monitoring, and cost limits.'],href:docs.alchemy}];
const checklist=[['Product decisions','Choose user-controlled vs custodial architecture, launch regions, minimum age, initial networks, assets, fees, and support model.'],['Business & provider approval','Confirm legal entity details and complete required partner review and KYB. No approval is implied by this preview.'],['Authentication & database','Implement real sign-in, session protection, wallet ownership authorization, an order state machine, audit logs, and backups.'],['Wallet & recovery tests','Prove new-wallet creation, account restore, send, receive, insufficient gas, wrong-network prevention, and signature rejection.'],['Payments & swaps','Verify quotes, fee disclosure, on/off-ramp events, refunds, price impact, allowances, idempotency, and provider outages.'],['Legal & operating review','Have qualified counsel assess the exact custody and transaction model, target markets, licensing, KYC/AML duties, privacy, and consumer terms.'],['Security review','Complete threat modeling, independent review of signing and backend logic, access control tests, secret management, monitoring, and an incident plan.'],['Controlled launch','Run end-to-end tests, then a limited rollout with provider approval, reconciliations, support staffing, and transaction limits.']];
function guide(){const count=Object.values(state.checks).filter(Boolean).length;return shell('Know the whole picture.','The connections, decisions, and work behind a live FYNX Wallet.',`<div class="guide-hero"><span class="eyebrow">FOUNDER’S BUILD GUIDE</span><h2>The interface is the beginning.<br>Here’s what makes it real.</h2><p class="muted">This site is an interactive prototype. It simulates transactions locally. The proposal below explains the services a real product needs; it does not claim those services are connected.</p></div><div class="guide-tabs"><a href="#guide" data-scroll="providers">01 Connections</a><a href="#guide" data-scroll="architecture">02 Architecture</a><a href="#guide" data-scroll="budget">03 Costs & revenue</a><a href="#guide" data-scroll="launch">04 Launch checklist</a></div><section id="providers"><div class="section-title"><h2>01 / What to connect</h2><span class="pill">All services: not connected</span></div><div class="card pad">${providers.map(p=>`<article class="integration"><span class="provider-icon">${p.mark}</span><div><h3>${p.name}</h3><span class="tiny">${p.provider}</span><p style="margin-top:12px">${p.desc}</p><details><summary>Connection steps & requirements</summary><ul>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ul></details><a class="textlink" target="_blank" rel="noopener noreferrer" href="${p.href}">Read official documentation ↗</a></div><span class="pill">To connect</span></article>`).join('')}<div class="info-box"><strong>Also required:</strong> real authentication (Firebase/Auth0 or equivalent), a backend, database, price feed, support system, error monitoring, notification delivery, and any additional identity or screening services required by your model. Providers overlap, so map responsibilities before buying services.</div></div></section><section id="architecture" style="margin-top:40px"><h2>02 / How it works together</h2><p class="muted" style="font-size:13px">Recommended starting scope: user-controlled wallets, one EVM network, ETH + USDC, a provider-hosted payment flow, and same-chain swaps. This is a design recommendation, not a guarantee of approval.</p><div class="flow-grid"><div><span class="eyebrow">01 / THE EXPERIENCE</span><b>FYNX website & iOS app</b><p>Portfolio, quotes, review screens, SDK authorization, transaction details, and support.</p></div><div><span class="eyebrow">02 / YOUR SERVER</span><b>Backend + database</b><p>Verify user access, keep secrets, sign provider requests, record orders, verify webhooks, and reconcile status.</p></div><div><span class="eyebrow">03 / CONNECTED SERVICES</span><b>Wallet, payment, swap & chain</b><p>The wallet signs with the user. The payment provider processes fiat. The swap service quotes. The network settles.</p></div></div><div class="card table-wrap"><table><thead><tr><th>Button</th><th>Production responsibility</th><th>Preview today</th></tr></thead><tbody>${[['Buy','Approved provider → order → crypto delivery','Local cash decreases; crypto increases'],['Sell','Provider deposit → verification → bank payout','Crypto decreases; local cash increases'],['Send','Address + network checks → signing → confirmation','Local transfer simulation'],['Receive','Wallet address + matching QR + monitoring','Invalid demo identifier only'],['Swap','Quote → allowance → user signature → settlement','Same-chain ETH / USDC simulation'],['Sign in','Identity provider → secure server session','No real account login'],['Security','MFA/passkeys, recovery, sessions, audit & response','Explanatory pages and a demo session']].map(r=>`<tr>${r.map(c=>`<td style="white-space:normal;min-width:135px;text-align:left;line-height:1.7">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="info-box"><strong>Keep payment data and keys out of the interface.</strong> Server-only secrets, verified webhooks, ownership checks, and idempotency are essential. A browser success screen is not proof that funds arrived. Never ask users for a seed phrase in a normal FYNX form.</div></section><section id="budget" style="margin-top:40px"><h2>03 / What it costs — and how it earns</h2><p class="muted" style="font-size:13px">There is no reliable all-in monthly quote yet. Get provider prices after deciding networks, active users, volume, custody, and launch countries. The earlier conversation’s prices should be rechecked before committing.</p><div class="two-cols"><div class="card pad"><h3>Your monthly cost worksheet</h3>${[['Hosting, database & auth','Plan + usage'],['Wallet provider','Active wallets / operations'],['RPC, indexing & prices','Requests / subscriptions'],['Swaps & payment processing','Plan + transaction fees'],['Compliance & support','Vendor + staff costs'],['Audits, legal & insurance','Up-front + recurring costs']].map(([a,b])=>`<div class="fee-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}<p class="hint">Add gas sponsorship, refunds, disputes, taxes, backups, and incident response. Low server costs do not mean a low-cost financial business.</p></div><div class="card pad"><h3>Possible revenue</h3><p class="muted" style="font-size:12px">Disclosed transaction fees where the provider agreement permits them, a paid analytics plan, or premium product features. No fee or revenue is guaranteed.</p><label class="label" for="volume">Illustrative monthly transaction volume ($)</label><input class="control" type="number" min="0" value="100000" id="volume"><label class="label" for="revenue-fee">Illustrative FYNX fee (%)</label><input class="control" type="number" min="0" max="100" step="0.1" value="0.5" id="revenue-fee"><div class="subcard"><span class="tiny">Gross revenue before all costs</span><h3 id="revenue-value" style="margin:8px 0">$500.00 / month</h3><span class="tiny">Arithmetic example only. Not profit or a forecast.</span></div></div></div></section><section id="launch" style="margin-top:40px"><div class="section-title"><h2>04 / Before the first real transaction</h2><span class="pill" id="check-count">${count} / ${checklist.length} reviewed</span></div><p class="tiny">Use this as a planning worksheet. Checking a box records that you reviewed the item; it does not certify completion or readiness.</p><div class="card pad"><div class="progress"><span id="check-progress" style="width:${count/checklist.length*100}%"></span></div>${checklist.map(([a,b],i)=>`<label class="check-row"><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span><b>${a}</b><small>${b}</small></span></label>`).join('')}<div class="info-box"><strong>Legal responsibilities follow the actual business model.</strong> Integrating a provider does not automatically remove FYNX’s obligations. Confirm the model with qualified counsel before handling customer funds. <a href="${docs.legal}" target="_blank" rel="noopener noreferrer" class="textlink">FinCEN guidance ↗</a></div></div></section><section class="faq" style="margin-top:40px"><h2>A few questions worth asking.</h2>${[['Can this work exactly like MoonPay?','You can build a FYNX-branded experience using payment and wallet services. Running your own payment rails, liquidity, custody, and compliance operation is a much larger business. A good interface alone does not provide those capabilities.'],['Can everything be done with one API key?','No. Wallet control, fiat payments, swaps, data, authentication, and operations have different responsibilities. Some providers combine services, but their scope and approvals must be checked.'],['What should launch first?','A reasonable first build is one network with user-controlled wallets, ETH and USDC, send/receive, then a provider-hosted buy/sell flow and same-chain swaps. Add Bitcoin, Solana, cross-chain routing, and hardware wallets after separate validation.'],['What must I decide now?','Your legal entity and supported countries, who controls funds, supported networks and assets, the recovery experience, pricing, and who handles compliance, customer support, refunds, and incidents.'],['What is actually working in this site?','Navigation, amount and balance checks, sample fee calculations, confirmation reviews, successful and failed local simulations, transaction detail pages, CSV export, local preferences, and the planning checklist. No provider account or blockchain is connected.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`,'guide')}
function networks(){return shell('Same wallet. Different networks.','Each asset belongs to a network. The live product must make that distinction clear.',`<div class="network-list">${[['Ethereum','ETH, USDC','Circle + EVM swap integration proposed','eth','♦'],['Base','ETH, USDC on Base','Separate chain configuration and balance tracking required','eth','◯'],['Solana','SOL, SPL tokens','Wallet support available; swap/signing compatibility needs validation','sol','≋'],['Bitcoin','BTC','Separate Bitcoin-compatible wallet, UTXO, fee, and indexing integration','btc','₿']].map(([a,b,c,d,i])=>`<div class="network-item"><span class="coin ${d}">${i}</span><div class="info"><b>${a}</b><small>${b}</small><small>${c}</small></div><span class="pill">Planned</span></div>`).join('')}</div><div class="info-box">This demo’s USDC and ETH swap runs only as a local Ethereum simulation. Base, Solana, and Bitcoin do not have live connectivity. A matching symbol does not imply that assets can be sent between networks.</div>${btn('Read integration requirements ↗','guide','light')}`,'networks')}
function support(security=false){return shell(security?'Report a security concern.':'A little help, right here.',security?'Prepare a clear report for a future verified reporting channel.':'Understand the preview and prepare a support request.',`<div class="two-cols"><div class="card pad"><h3>${security?'Security report draft':'Support request draft'}</h3><p class="tiny">This form prepares text locally. It does not send a message. Do not include passwords, private keys, recovery phrases, card details, or identity documents.</p><form id="support-form" data-security="${security}"><label class="label" for="support-topic">Topic</label><select class="control" id="support-topic">${(security?['Potential vulnerability','Account protection concern','Transaction safety concern']:['Wallet & balances','Buy & sell','Transfers','Swaps','General question']).map(x=>`<option>${x}</option>`).join('')}</select><label class="label" for="support-message">${security?'What did you observe?':'How can we help?'}</label><textarea class="control" id="support-message" rows="5" minlength="10" maxlength="3000" required placeholder="Describe the issue and the steps to reproduce it…"></textarea><div class="error" id="support-error"></div><button class="button wide">Prepare draft ${icon('arrow')}</button></form></div><div><h3>Good to know.</h3><div class="faq">${[['Where are my funds?','There are no real funds in the preview. The starting holdings and test spending balance are fictional.'],['Why did a transaction fail?','The test-outcome control lets you simulate a provider outage or rejected authorization. Failed simulations leave balances unchanged.'],['Does this create a real wallet?','No. Real address generation, QR codes, signing, account access, and recovery need wallet-provider integration.'],['Can I clear my data?','Yes. Open Settings → Data → Reset demo. This restores starting balances, preferences, activity, and checklist choices.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="info-box">A verified support inbox, service expectations, and a security-reporting process need to be established before launch. This prototype does not offer a bug bounty.</div></div></div>`,'support')}
function legal(type){let privacy=type==='privacy';return shell(privacy?'Privacy, in plain sight.':'A clear starting point.',privacy?'How this interactive preview handles information.':'Terms for exploring this product concept.',`<article class="longform"><span class="pill">Preview notice · not production legal terms</span><h2>${privacy?'Your local preview data':'About this demo'}</h2><p>${privacy?'This preview saves simulated balances, transaction records, your display name, interface preferences, and checklist selections in browser local storage. It does not create a financial account. Do not enter sensitive financial, identity, or recovery information.':'FYNX Wallet is currently a design concept. All balances, prices, fees, payment methods, and transaction outcomes shown here are illustrative. No real purchase, sale, transfer, swap, or wallet creation is performed.'}</p><h2>${privacy?'Connections and third-party services':'What the prototype provides'}</h2><p>${privacy?'No wallet, payment, market-data, or authentication provider is connected. This archived prototype runs locally. The public FYNX website is hosted on GitHub Pages. Google Fonts is requested for typography, so the font service receives standard request information such as IP address. Official documentation links open third-party websites with their own policies.':'You may explore navigation, sample calculations, local transaction simulations, transaction exports, and the launch-planning worksheet. Rates and fee assumptions are not executable quotes or investment advice. You must not attempt to send funds to a demo identifier.'}</p><h2>${privacy?'Control and deletion':'Before a real launch'}</h2><p>${privacy?'You can reset local preview data in Settings → Data, or clear this site’s storage in your browser. Local data is not an encrypted financial ledger and may be visible to someone using your device or browser profile.':'The operating company, launch countries, minimum age, custody model, fee policies, dispute/refund handling, privacy policy, user agreement, compliance duties, and support channels must be finalized. These preview notices do not replace reviewed production legal documents.'}</p><h2>Contact</h2><p>The verified support and privacy-request channels for this proposed product are still to be established. You can prepare a local request draft on the support page; it is not transmitted.</p><div class="flex">${btn('Manage preview data','settings/data','light')}${btn('Support draft','support','soft')}</div></article>`,type)}
function footer(){return `<div class="footer-grid"><div class="footer-brand"><a class="brand" href="#home">FYNX <small>Wallet</small></a><p>A calmer place for your crypto.<br>An interactive look at what’s next.</p><div class="socials"><a href="#support" aria-label="Contact support">${icon('mail')}</a><button data-act="copy-site" aria-label="Copy site link">${icon('link')}</button><a href="#security" aria-label="Security information">${icon('shield')}</a></div><p style="margin-top:28px">© 2026 FYNX Wallet.<br>Product concept. All activity is simulated.</p></div><div class="footer-links"><h3>Product</h3><a href="#wallet">My wallet</a><a href="#buy">Buy & sell</a><a href="#swap">Swap crypto</a><a href="#networks">Networks</a><a href="#guide">Build guide</a></div><div class="footer-links"><h3>Resources</h3><a href="#privacy">Privacy</a><a href="#terms">Terms</a><a href="#support">Contact</a><a href="#security">Security</a><a href="#settings">Settings</a></div></div><div class="footer-security"><div><span class="eyebrow">SECURITY & PRIVACY</span><div class="trust-icons"><span>${icon('lock')}User control</span><span>${icon('shield')}Clear permissions</span><span>${icon('eye')}Transparent design</span></div><p>User-controlled wallets are the proposed direction. No audit, certification, or live security service is claimed.</p></div><div><h3 style="font-size:16px">A thoughtful approach to security.</h3><p>Found something we should look at? Prepare a report for the future support channel. No bug bounty is active.</p><a class="textlink" style="font-size:14px;font-weight:600" href="#support/security">Report a security concern ${icon('arrow')}</a></div></div>`}
$('#footer').innerHTML=footer();
function bindAssets(){$$('[data-asset]').forEach(r=>{r.onclick=()=>location.hash='asset/'+r.dataset.asset;r.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();location.hash='asset/'+r.dataset.asset}}})}
function drawChart(r='1M'){if(!$('#chart-line'))return;let seed=['1D','1W','1M','1Y','ALL'].indexOf(r)+1,a=Array.from({length:35},(_,i)=>145-i*3.7+Math.sin(i*1.9+seed)*8+Math.cos(i*.6+seed)*11),p='M'+a.map((y,i)=>`${i*700/(a.length-1)} ${y}`).join('L');$('#chart-line').setAttribute('d',p);$('#chart-area').setAttribute('d',p+'L700 170L0 170Z');$('#chart-dates').innerHTML=({'1D':['12 AM','6 AM','12 PM','6 PM','Now'],'1W':['Oct 10','Oct 12','Oct 14','Oct 16','Oct 17'],'1M':['Sep 17','Sep 24','Oct 01','Oct 08','Oct 17'],'1Y':['Oct 2025','Jan','Apr','Jul','Oct 2026'],'ALL':['2022','2023','2024','2025','2026']}[r]).map(x=>`<span>${x}</span>`).join('');$$('[data-range]').forEach(b=>{b.classList.toggle('active',b.dataset.range===r);b.setAttribute('aria-pressed',b.dataset.range===r)})}
function csv(){let header=['reference','type','asset','quantity','receive_asset','receive_quantity','status','network','date','demo_fee_usd'];const safe=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let rows=state.txs.map(t=>[t.id,t.type,t.s,t.qty,t.to,t.out,t.status,t.network,t.date,t.fee]);let blob=new Blob(['DEMO DATA - NOT A FINANCIAL RECORD\r\n'+[header,...rows].map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fynx-demo-transactions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo activity exported')}
function action(a){if(a==='hide'){state.prefs.hide=!state.prefs.hide;save();render()}if(a==='export')csv();if(a==='copy-site')copy(location.origin+location.pathname+'#home');if(a==='reset'){modal('Start fresh?',`<p>This clears simulated transactions, balances, profile preferences, and reviewed checklist choices from this browser and restores the sample portfolio.</p><button class="button wide" id="reset-confirm">Reset this preview</button><button class="textlink wide" id="reset-cancel" style="margin-top:18px">Keep my demo data</button>`);$('#reset-cancel').onclick=()=>$('#dialog').close();$('#reset-confirm').onclick=()=>{state=structuredClone(initial);save();$('#dialog').close();render();toast('Preview restored to sample data')}}if(a==='session-demo'){modal('A session control, previewed.',`<p>The live product needs an authenticated device list with server-side revocation. Below is only a demonstration.</p><div class="subcard"><b>Example browser session</b><p id="session-status">Demo session · active</p><button class="button light" id="revoke-session">Simulate revoke</button></div><p class="hint">This does not sign you out of the owner workspace or protect a real account.</p>`);$('#revoke-session').onclick=()=>{$('#session-status').textContent='Demo session · revoked';$('#revoke-session').disabled=true;$('#revoke-session').textContent='Revoked in preview'}}if(a==='recovery')modal('Recovery needs a complete plan.',`<p>Before launch, choose a provider-supported recovery design and test:</p><ol class="muted" style="font-size:13px;line-height:1.9"><li>Lost device and restored account access.</li><li>Lost authentication method and compromised account.</li><li>Recovery authorization, delays, and user alerts.</li><li>What happens if FYNX or the wallet provider is unavailable.</li></ol><p>No recovery phrase or key exists in this demo.</p><a href="#guide" class="button wide" id="recovery-guide">Read the build guide ↗</a>`);if($('#recovery-guide'))$('#recovery-guide').onclick=()=>$('#dialog').close()}
function bind(){bindAssets();bindExchange();bindSend();bindReceive();drawChart();$$('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);$$('[data-range]').forEach(b=>b.onclick=()=>drawChart(b.dataset.range));$$('[data-tx]').forEach(b=>b.onclick=()=>location.hash='transaction/'+b.dataset.tx);$$('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act));if($('#asset-search'))$('#asset-search').oninput=e=>{$('#asset-results').innerHTML=assetTable(assets.filter(c=>(c.name+' '+c.s).toLowerCase().includes(e.target.value.toLowerCase())));bindAssets()};function filterActivity(){let type=$('#activity-filter').value,status=$('#status-filter').value;$('#activity-list').innerHTML=txList(state.txs.filter(t=>(type==='all'||t.type===type)&&(status==='all'||t.status===status)));$$('[data-tx]').forEach(b=>b.onclick=()=>location.hash='transaction/'+b.dataset.tx)}if($('#activity-filter')){$('#activity-filter').onchange=filterActivity;$('#status-filter').onchange=filterActivity}if($('#copy-reference'))$('#copy-reference').onclick=e=>copy(e.currentTarget.dataset.reference);if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();let name=$('#display-name').value.trim();if(!name)return;state.prefs.name=name;save();toast('Demo profile saved')};$$('[data-pref]').forEach(b=>b.onclick=()=>{let k=b.dataset.pref;state.prefs[k]=!state.prefs[k];b.setAttribute('aria-checked',state.prefs[k]);save();toast('Preview preference saved')});$$('[data-check]').forEach(b=>b.onchange=()=>{state.checks[b.dataset.check]=b.checked;save();let count=Object.values(state.checks).filter(Boolean).length;$('#check-count').textContent=`${count} / ${checklist.length} reviewed`;$('#check-progress').style.width=count/checklist.length*100+'%'});$$('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.scroll).scrollIntoView({behavior:'smooth',block:'start'})});function revenue(){let v=Number($('#volume').value),f=Number($('#revenue-fee').value);$('#revenue-value').textContent=Number.isFinite(v)&&v>=0&&f>=0&&f<=100?money(v*f/100)+' / month':'Enter a valid volume and fee (0–100%).'}if($('#volume')){$('#volume').oninput=revenue;$('#revenue-fee').oninput=revenue}if($('#support-form'))$('#support-form').onsubmit=e=>{e.preventDefault();let topic=$('#support-topic').value,msg=$('#support-message').value.trim();if(msg.length<10){$('#support-error').textContent='Add at least 10 characters describing the issue.';return}let draft=`FYNX Wallet ${$('#support-form').dataset.security==='true'?'security':'support'} draft\nTopic: ${topic}\n\n${msg}\n\nPrepared locally. Not sent.`;modal('Your draft is ready.',`<p>Copy this draft to your verified support channel when one is established. Nothing has been sent.</p><textarea class="control" rows="8" id="support-draft" readonly>${escape(draft)}</textarea><button class="button wide" id="copy-draft">${icon('copy')} Copy draft</button>`);$('#copy-draft').onclick=()=>copy(draft)}}
function render(){let [route='home',detail]=location.hash.slice(1).split('/');if(!route)route='home';let content;switch(route){case'home':content=home();break;case'wallet':content=wallet();break;case'assets':content=allAssets();break;case'asset':content=assetDetail(detail);break;case'buy':case'sell':case'swap':case'send':case'receive':content=tradePage(route,detail);break;case'activity':content=activity();break;case'transaction':content=txDetail(detail);break;case'settings':content=settings(['profile','preferences','connections','data'].includes(detail)?detail:'profile');break;case'security':content=security();break;case'guide':content=guide();break;case'networks':content=networks();break;case'support':content=support(detail==='security');break;case'privacy':case'terms':content=legal(route);break;default:content=shell('Let’s get you back.','This page is not part of the preview.',btn('Back to your wallet','wallet'),'404')}$('#app').innerHTML=content;$('#footer').innerHTML=footer();$$('.globalnav>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#mobile-links').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');document.title='FYNX Wallet — '+({home:'Crypto, simply yours.',wallet:'Overview',guide:'Before launch',assets:'Your assets',activity:'Activity',security:'Security',settings:'Preferences'}[route]||route[0].toUpperCase()+route.slice(1));bind()}
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();render();window.scrollTo(0,0)});render();
